if "first_hit_example" in R: p += [f"Приклад, де reranking змінив позицію першої релевантної відповіді: {R['first_hit_example']['qid']} («{R['first_hit_example']['query']}») — {R['first_hit_example']['before']} → {R['first_hit_example']['after']}.", ""]
